import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - like rerouting power through the secondary coupling
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Isolinear Chip', price: 29.99 },
  { id: '2', name: 'Plasma Conduit', price: 149.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 179.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '1701 Enterprise Drive',
  city: 'San Francisco',
  state: 'CA',
  zip: '94102'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Miles O\'Brien'
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-47' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/isolinear chip/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/ORD-47/)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-47');
    });
  });

  describe('Form Validation', () => {
    it('displays error when street address is empty', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to payment
      await user.type(screen.getByLabelText(/street/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), '94102');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Error States and Recovery', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Insufficient credits'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate through to review
      // ... (fill forms as above)

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/insufficient credits/i);
      });

      // Retry should be possible
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-48' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
    });
  });

  describe('Loading States', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review and submit
      // ... (fill forms)

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValueOnce({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('has proper progress navigation landmarks', () => {
      render(<Checkout />);
      expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
      expect(screen.getByText('Shipping')).toHaveAttribute('aria-current', 'step');
    });
  });
});
